INSERT IGNORE INTO diseases(code,name,scientific_name,description,advice) VALUES
('P001','Karat daun kopi','Hemileia vastatrix','Penyakit jamur pada daun. Gejala khas berupa bercak kuning hingga jingga dan serbuk spora pada permukaan bawah daun.','Amati sisi bawah daun dan catat sebaran bercak. Konsultasikan pengendalian terpadu dengan penyuluh setempat.'),
('P002','Bercak daun Cercospora','Cercospora coffeicola','Bercak cokelat pada daun; infeksi juga dapat tampak sebagai bercak pada buah.','Periksa bercak pada kedua sisi daun dan buah. Evaluasi kondisi naungan, nutrisi, serta kelembapan kebun.'),
('P003','Antraknosa kopi','Colletotrichum spp.','Infeksi dapat menimbulkan lesi gelap pada buah dan jaringan tanaman, serta kematian pucuk pada kondisi tertentu.','Periksa buah dan pucuk terdampak; lakukan sanitasi dan minta konfirmasi petugas bila meluas.'),
('P004','Penyakit buah kopi (CBD)','Colletotrichum kahawae','Penyakit buah yang menimbulkan lesi gelap cekung, buah muda gugur atau mengering.','Amati lesi pada buah dan tingkat kerontokan. Konfirmasikan penyebab karena gejala dapat tumpang tindih.'),
('P005','Layu / mati pucuk','Fusarium spp. / kompleks penyebab layu','Gejala layu dan kematian cabang dapat berasal dari beberapa penyebab; identifikasi lapang saja belum memastikan patogen.','Periksa pola layu dan kondisi akar atau pangkal batang. Minta pemeriksaan penyuluh atau laboratorium.');
INSERT IGNORE INTO symptoms(code,name,description,category) VALUES
('G001','Ada bercak atau perubahan warna pada daun','Amati permukaan atas dan bawah daun.','umum'),
('G002','Daun menguning atau tampak pucat','Perubahan warna dapat muncul merata atau berupa bercak.','umum'),
('G003','Daun rontok atau jumlah daun berkurang','Perhatikan kerontokan yang tidak biasa pada satu cabang atau tanaman.','umum'),
('G004','Buah kopi memiliki bercak, luka, atau perubahan warna','Amati buah muda maupun buah yang mulai matang.','umum'),
('G005','Cabang atau pucuk mengering / tanaman tampak layu','Periksa bagian pucuk, cabang, dan pangkal tanaman.','umum'),
('G006','Serbuk jingga terlihat di sisi bawah daun','Bercak kuning-jingga seperti serbuk pada permukaan bawah daun.','khusus'),
('G007','Bercak daun cokelat memiliki tepi kemerahan','Bercak dapat muncul di kedua sisi daun.','khusus'),
('G008','Bercak buah berupa luka gelap yang cekung','Lesi tampak masuk ke dalam permukaan buah.','khusus'),
('G009','Buah muda menghitam, mengering, atau gugur','Buah yang terkena dapat mengering atau rontok lebih awal.','khusus'),
('G010','Daun atau buah memiliki bercak berminyak / nekrotik','Perubahan jaringan dapat meluas menjadi jaringan mati.','khusus'),
('G011','Pucuk mati atau cabang mengering dari ujung','Kematian jaringan terlihat pada pucuk atau cabang.','khusus'),
('G012','Layu tetap terjadi meski tanaman mendapat cukup air','Bandingkan dengan tanaman sehat dan periksa kondisi pangkal/akar.','khusus'),
('G013','Ada luka gelap pada buah disertai buah rontok','Periksa beberapa buah dalam satu tanaman.','khusus'),
('G014','Bercak daun tampak kuning lalu berkembang menjadi jingga','Gejala dapat disertai daun rontok jika serangan berat.','khusus');
INSERT IGNORE INTO rules(disease_id,symptom_id,cf_expert,note) SELECT d.id,s.id,x.cf,x.src FROM (SELECT 'P001' p,'G001' g,.65 cf,'Review CLR 2024; Embrapa 2024' src UNION ALL SELECT 'P001','G002',.45,'Review CLR 2024; Embrapa 2024' UNION ALL SELECT 'P001','G003',.55,'Review CLR 2024' UNION ALL SELECT 'P001','G006',.95,'Review CLR 2024: pustula jingga pada daun' UNION ALL SELECT 'P001','G014',.9,'Review CLR 2024') x JOIN diseases d ON d.code=x.p JOIN symptoms s ON s.code=x.g;
INSERT IGNORE INTO rules(disease_id,symptom_id,cf_expert,note) SELECT d.id,s.id,x.cf,x.src FROM (SELECT 'P002' p,'G001' g,.8 cf,'Panduan diagnosis; gejala bercak daun' src UNION ALL SELECT 'P002','G004',.45,'Panduan Cercospora' UNION ALL SELECT 'P002','G007',.9,'Manual Arabica FAO; ciri bercak' UNION ALL SELECT 'P003','G001',.35,'Colletotrichum coffee anthracnose, 2025' UNION ALL SELECT 'P003','G004',.7,'Colletotrichum coffee anthracnose, 2025' UNION ALL SELECT 'P003','G005',.4,'Colletotrichum coffee anthracnose, 2025' UNION ALL SELECT 'P003','G010',.85,'Colletotrichum coffee anthracnose, 2025' UNION ALL SELECT 'P003','G011',.75,'Colletotrichum coffee anthracnose, 2025' UNION ALL SELECT 'P004','G004',.8,'Arabica Coffee Handbook; gejala CBD' UNION ALL SELECT 'P004','G008',.9,'Arabica Coffee Handbook; lesi cekung' UNION ALL SELECT 'P004','G009',.8,'Arabica Coffee Handbook; buah gugur/mumi' UNION ALL SELECT 'P004','G013',.85,'Arabica Coffee Handbook; lesi dan kerontokan' UNION ALL SELECT 'P005','G002',.35,'Coffee wilt disease review, 2024' UNION ALL SELECT 'P005','G003',.45,'Coffee wilt disease review, 2024' UNION ALL SELECT 'P005','G005',.8,'Coffee wilt disease review, 2024' UNION ALL SELECT 'P005','G011',.65,'Coffee wilt disease review, 2024' UNION ALL SELECT 'P005','G012',.7,'Coffee wilt disease review, 2024') x JOIN diseases d ON d.code=x.p JOIN symptoms s ON s.code=x.g;
