CREATE DATABASE IF NOT EXISTS kopi_cf CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE kopi_cf;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('user','admin') NOT NULL DEFAULT 'user',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS symptoms(id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(12) NOT NULL UNIQUE,name VARCHAR(180) NOT NULL,description TEXT NULL,category ENUM('umum','khusus') NOT NULL DEFAULT 'umum',active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS diseases(id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(12) NOT NULL UNIQUE,name VARCHAR(180) NOT NULL,scientific_name VARCHAR(180) NULL,description TEXT NULL,advice TEXT NULL,active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rules(id INT AUTO_INCREMENT PRIMARY KEY,disease_id INT NOT NULL,symptom_id INT NOT NULL,cf_expert DECIMAL(4,2) NOT NULL DEFAULT 0.80,note VARCHAR(255) NULL,UNIQUE KEY uq_rule(disease_id,symptom_id),CONSTRAINT fk_rule_disease FOREIGN KEY(disease_id) REFERENCES diseases(id) ON DELETE CASCADE,CONSTRAINT fk_rule_symptom FOREIGN KEY(symptom_id) REFERENCES symptoms(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS diagnoses(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,disease_name VARCHAR(180) NOT NULL,confidence DECIMAL(5,2) NOT NULL,results_json LONGTEXT NOT NULL,answers_json LONGTEXT NOT NULL,general_json LONGTEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,created_at),CONSTRAINT fk_diag_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
